def solve(grid):
    """Count the number of islands (connected components of 1s) in a grid.
    Connections are 4-directional (up, down, left, right).
    """
    if not grid:
        return 0
    rows = len(grid)
    cols = len(grid[0]) if rows else 0
    if cols == 0:
        return 0
    visited = [[False] * cols for _ in range(rows)]
    def dfs(r, c):
        stack = [(r, c)]
        while stack:
            i, j = stack.pop()
            if i < 0 or i >= rows or j < 0 or j >= cols:
                continue
            if visited[i][j] or grid[i][j] == 0:
                continue
            visited[i][j] = True
            stack.append((i - 1, j))
            stack.append((i + 1, j))
            stack.append((i, j - 1))
            stack.append((i, j + 1))
    islands = 0
    for i in range(rows):
        for j in range(cols):
            if grid[i][j] == 1 and not visited[i][j]:
                islands += 1
                dfs(i, j)
    return islands

