def solve(path: str) -> str:
    """Simplify an absolute Unix file path.
    Resolve '.' (current directory) and '..' (parent directory), collapse
    multiple slashes, and ensure the result starts with '/' and has no trailing
    slash (except for root).
    """
    # Use a stack to build the canonical path components
    stack = []
    for token in path.split('/'):
        if token == '' or token == '.':
            # Empty token results from consecutive slashes or leading slash – ignore
            # '.' refers to current directory – ignore as well
            continue
        if token == '..':
            # Go up one directory if possible; otherwise stay at root
            if stack:
                stack.pop()
        else:
            # Normal directory name – push onto stack
            stack.append(token)
    # Reconstruct the simplified path
    return '/' + '/'.join(stack)

