def solve(matrix):
    """Return integer determinant of a square matrix.
    Uses fraction-free Bareiss algorithm for exact integer result.
    Empty matrix returns 1 by definition.
    """
    n = len(matrix)
    if n == 0:
        return 1
    # copy matrix
    A = [row[:] for row in matrix]
    det_sign = 1
    prev = 1
    for k in range(n-1):
        # ensure pivot is non-zero
        if A[k][k] == 0:
            swap = None
            for i in range(k+1, n):
                if A[i][k] != 0:
                    swap = i
                    break
            if swap is None:
                return 0
            A[k], A[swap] = A[swap], A[k]
            det_sign = -det_sign
        pivot = A[k][k]
        for i in range(k+1, n):
            for j in range(k+1, n):
                A[i][j] = (A[i][j] * pivot - A[i][k] * A[k][j]) // prev
        prev = pivot
    return det_sign * A[n-1][n-1]

