def solve(n, b):
    """Convert integer n to a string representation in base b (2 <= b <= 36).
    Negative numbers get a leading '-'. Zero returns '0'. Digits 0-9 then a-z are used.
    """
    if b < 2 or b > 36:
        raise ValueError("Base out of supported range")
    if n == 0:
        return "0"
    digits = "0123456789abcdefghijklmnopqrstuvwxyz"
    sign = ''
    if n < 0:
        sign = '-'
        n = -n
    res_chars = []
    while n > 0:
        n, rem = divmod(n, b)
        res_chars.append(digits[rem])
    return sign + ''.join(reversed(res_chars))

