def solve(a, b):
    """Return Levenshtein distance between strings a and b.
    Implements O(min(m,n)) space DP with early shortcuts for equal strings
    and empty inputs to handle large test cases efficiently.
    """
    # Fast paths
    if a == b:
        return 0
    if not a:
        return len(b)
    if not b:
        return len(a)
    # Ensure a is the shorter string to minimize space
    if len(a) > len(b):
        a, b = b, a
    m, n = len(a), len(b)
    # prev[i] = distance between a[:i] and b[:j-1] (previous row)
    prev = list(range(m + 1))
    for j in range(1, n + 1):
        cur = [j] + [0] * m
        bj = b[j - 1]
        # Early termination: if minimal possible distance exceeds current best?
        for i in range(1, m + 1):
            cost = 0 if a[i - 1] == bj else 1
            # deletion (prev[i] + 1), insertion (cur[i-1] + 1), substitution (prev[i-1] + cost)
            cur[i] = min(prev[i] + 1, cur[i - 1] + 1, prev[i - 1] + cost)
        prev = cur
    return prev[m]

