def solve(coins, amount):
    # Edge cases
    if amount < 0:
        return -1
    if amount == 0:
        return 0
    # Initialize DP array with a large number
    INF = amount + 1  # larger than any possible coin count
    dp = [INF] * (amount + 1)
    dp[0] = 0
    for coin in coins:
        for x in range(coin, amount + 1):
            if dp[x - coin] + 1 < dp[x]:
                dp[x] = dp[x - coin] + 1
    return dp[amount] if dp[amount] != INF else -1

